{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.INT_SALES PARTITION BY order_date AS SELECT DATE(order_date) AS order_date, LOWER(TRIM(CAST(product_id AS STRING))) AS product_id, REGEXP_REPLACE(LOWER(TRIM(sku)), r\'[^a-z0-9]\', \'\') AS SKU, ANY_VALUE(PRODUCT_NAME_FINAL) AS product_name, SUM(IFNULL(selling_price,0)) AS sales FROM `maplemonk.maplemonk_analytics_sales_consolidated` GROUP BY 1,2,3; CREATE OR REPLACE TABLE MAPLEMONK.INT_SKU_MAP AS SELECT LOWER(TRIM(CAST(channel_product_id AS STRING))) AS product_id, REGEXP_REPLACE(LOWER(TRIM(sku_code)), r\'[^a-z0-9]\', \'\') AS SKU FROM `maplemonk-analytics.maplemonk.unicommerce_fytika_get_product_listing` WHERE mrp IS NOT NULL QUALIFY ROW_NUMBER() OVER ( PARTITION BY channel_product_id ORDER BY DATE(updated) DESC ) = 1; CREATE OR REPLACE TABLE MAPLEMONK.INT_PRODUCT_MASTER AS SELECT REGEXP_REPLACE(LOWER(product_code), r\'[^a-z0-9]\', \'\') AS SKU, UPPER(name) AS product_name, UPPER(category_name) AS category FROM `maplemonk-analytics.maplemonk.unicommerce_fytika_get_product_master` QUALIFY ROW_NUMBER() OVER ( PARTITION BY product_code ORDER BY DATE(updated) DESC ) = 1; CREATE OR REPLACE TABLE MAPLEMONK.INT_CHANNEL_SPEND AS SELECT LOWER(TRIM(channel)) AS channel, DATE(date) AS date, SUM(CAST(spend AS FLOAT64)) AS total_channel_spend FROM `maplemonk.maplemonk_analytics_MARKETING_CONSOLIDATED` GROUP BY 1,2; CREATE OR REPLACE TABLE MAPLEMONK.INT_AMAZON_CHANNEL_SPEND AS SELECT \'amazon\' AS channel, DATE(date) AS date, SUM(spend) AS total_channel_spend FROM `maplemonk-analytics.maplemonk.fytika_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED` GROUP BY 1,2; CREATE OR REPLACE TABLE MAPLEMONK.INT_FACEBOOK AS SELECT DATE(fc.Date) AS date, LOWER(fc.Channel) AS channel, LOWER(TRIM(CAST(fc.product_id AS STRING))) AS product_id, SUM(fc.Clicks) AS clicks, SUM(fc.Spend) AS spend, SUM(fc.Impressions) AS impressions, SUM(fc.Conversions) AS conversions, SUM(fc.Conversion_Value) AS conversion_value, ANY_VALUE(COALESCE(sm.SKU, s.SKU)) AS SKU, SUM(IFNULL(s.sales,0)) AS sales FROM `maplemonk.fytika_db_Product_FACEBOOK_CONSOLIDATED` fc LEFT JOIN MAPLEMONK.INT_SKU_MAP sm ON LOWER(TRIM(CAST(fc.product_id AS STRING))) = sm.product_id LEFT JOIN MAPLEMONK.INT_SALES s ON LOWER(TRIM(CAST(fc.product_id AS STRING))) = s.product_id and date(fc.Date) = s.order_date GROUP BY 1,2,3; CREATE OR REPLACE TABLE MAPLEMONK.INT_GOOGLE AS SELECT DATE(gc.Date) AS date, LOWER(gc.Channel) AS channel, LOWER(TRIM(SPLIT(gc.segments_product_item_id, \'_\')[SAFE_OFFSET(2)])) AS product_id, SUM(gc.clicks) AS clicks, SUM(gc.spend) AS spend, SUM(gc.Impressions) AS impressions, SUM(gc.Conversions) AS conversions, SUM(gc.Conversion_Value) AS conversion_value, ANY_VALUE(COALESCE(sm.SKU, s.SKU)) AS SKU, SUM(IFNULL(s.sales,0)) AS sales FROM `maplemonk.Fytika_db_Product_GOOGLEADS_CONSOLIDATED` gc LEFT JOIN MAPLEMONK.INT_SKU_MAP sm ON LOWER(TRIM(SPLIT(gc.segments_product_item_id, \'_\')[SAFE_OFFSET(2)])) = sm.product_id LEFT JOIN MAPLEMONK.INT_SALES s ON LOWER(TRIM(SPLIT(gc.segments_product_item_id, \'_\')[SAFE_OFFSET(2)])) = s.product_id and date(gc.Date) = s.order_date GROUP BY 1,2,3; CREATE OR REPLACE TABLE MAPLEMONK.INT_AMAZON AS SELECT DATE(a.Date) AS date, \'amazon\' AS channel, LOWER(TRIM(a.channel_product_id)) AS product_id, SUM(a.clicks) AS clicks, SUM(a.spend) AS spend, SUM(a.impressions) AS impressions, SUM(a.ATTRIBUTED_CONVERSIONS_14D) AS conversions, SUM(a.ATTRIBUTED_SALES_14D) AS conversion_value, ANY_VALUE(COALESCE(sm.SKU, s.SKU))AS SKU, SUM(IFNULL(s.sales,0)) AS sales FROM `maplemonk-analytics.maplemonk.fytika_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED` a LEFT JOIN MAPLEMONK.INT_SKU_MAP sm ON LOWER(TRIM(a.channel_product_id)) = sm.product_id LEFT JOIN MAPLEMONK.INT_SALES s ON LOWER(TRIM(a.channel_product_id)) = s.product_id and date(a.Date) = s.order_date WHERE a.channel_product_id IS NOT NULL GROUP BY 1,2,3; CREATE OR REPLACE TABLE MAPLEMONK.INT_FLIPKART AS SELECT DATE(fk.Date) AS date, LOWER(fk.Channel) AS channel, LOWER(TRIM(fk.product_id)) AS product_id, SUM(fk.Clicks) AS clicks, SUM(fk.Spend) AS spend, SUM(fk.Impressions) AS impressions, SUM(fk.Conversions) AS conversions, SUM(fk.Conversion_Value) AS conversion_value, REGEXP_REPLACE(LOWER(TRIM(fk.sku)), r\'[^a-z0-9]\', \'\') AS SKU, SUM(fk.sales) AS sales FROM `maplemonk.Fytika_db_Product_Flipkart_FSN` fk GROUP BY 1,2,3,9; CREATE OR REPLACE TABLE MAPLEMONK.INT_MARKETING_COMBINED AS SELECT * FROM MAPLEMONK.INT_FACEBOOK UNION ALL SELECT * FROM MAPLEMONK.INT_GOOGLE UNION ALL SELECT * FROM MAPLEMONK.INT_AMAZON UNION ALL SELECT * FROM MAPLEMONK.INT_FLIPKART; DROP TABLE IF EXISTS MAPLEMONK.FYTIKA_DB_PRODUCT_MARKETING_CONSOLIDATED; CREATE OR REPLACE TABLE MAPLEMONK.FYTIKA_DB_PRODUCT_MARKETING_CONSOLIDATED PARTITION BY date AS WITH base AS ( SELECT m.*, SUM(spend) OVER (PARTITION BY date, channel) AS total_spend, SUM(sales) OVER (PARTITION BY date, channel) AS total_sales FROM MAPLEMONK.INT_MARKETING_COMBINED m ) SELECT b.*, pm.product_name, pm.category, COALESCE( CASE WHEN b.channel = \'amazon\' THEN ac.total_channel_spend ELSE cs.total_channel_spend END, 0 ) AS total_channel_spend, GREATEST( CASE WHEN b.total_sales != 0 THEN b.spend + ( IFNULL( CASE WHEN b.channel = \'amazon\' THEN ac.total_channel_spend ELSE cs.total_channel_spend END, b.total_spend ) - b.total_spend ) * (b.sales / b.total_sales) ELSE b.spend END, 0 ) AS corrected_spend FROM base b LEFT JOIN MAPLEMONK.INT_CHANNEL_SPEND cs ON b.channel = cs.channel AND b.date = cs.date LEFT JOIN MAPLEMONK.INT_AMAZON_CHANNEL_SPEND ac ON b.channel = ac.channel AND b.date = ac.date LEFT JOIN MAPLEMONK.INT_PRODUCT_MASTER pm ON b.SKU = pm.SKU;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            